                        *ignore_text = true;
                        *outix += attrcopy_utf8(&outbuf[*outix], attr1, n_outbuf-*outix);
                }
                break;
        case SSML_IGNORE_TEXT:
                *ignore_text = true;
                break;
        case SSML_SUB + SSML_CLOSE:
        case SSML_IGNORE_TEXT + SSML_CLOSE:
