                                // This is the marker we are waiting for before starting to speak
                                *clear_skipping_text = true;
                                skip_marker[0] = 0;
                                return CLAUSE_NONE;
                        }

                        if ((index = AddNameData(buf, 0)) >= 0) {
                                sprintf(buf, "%c%dM", CTRL_EMBEDDED, index);
                                strcpy(&outbuf[*outix], buf);
                                *outix += strlen(buf);
