                        return 0; // no voice change
                return CLAUSE_VOICE;
        case SSML_VOICE:
                if (GetVoiceAttributes(px, tag_type, ssml_sp, ssml_stack, *n_ssml_stack, current_voice_id, base_voice, base_voice_variant_name) == 0)
