   422
   423                  namedata = (char *)vp;
   424                  n_namedata = namedata_ix+len + 1000;
   425          }
   426          memcpy(&namedata[ix = namedata_ix], name, len);
   427          namedata_ix += len;
   428          return ix;
   429  }
